cat >> src/orchestration/tools/registry.test.ts <<'EOF'

describe('ToolRegistry function-valued definitions', () => {
  it('validates each call against the inputSchema returned for that call, not a stale one', async () => {
    const registry = new ToolRegistry();
    let current = 'location';
    const schemaFor = (required: string) => ({
      type: 'object' as const,
      properties: {[required]: {type: 'string' as const}},
      required: [required],
    });
    let executorCalls = 0;
    registry.register(
      () => ({name: 'lookup', description: 'Look up', inputSchema: schemaFor(current)}),
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const rejected = await registry.execute('lookup', {city: 'Oslo'});
    current = 'city';
    const accepted = await registry.execute('lookup', {city: 'Oslo'});

    expect({
      firstRejected: rejected.result.includes('location'),
      secondResult: accepted.result,
      executorCalls,
    }).toEqual({
      firstRejected: true,
      secondResult: 'ok',
      executorCalls: 1,
    });
  });
});
EOF
grep -n "validated by\|Validated" -r specs/hal-engine-tool-input-validation/spec.md | head -3; grep -n "^it(\|^  it(\|validates each call" src/orchestration/tools/registry.test.ts
